"""Official code owners of kubernetes/kubernetes, read from its OWNERS files.

    from owners import owners_for_path
    owners_for_path("pkg/scheduler/framework")
    -> {"approvers": {"macsko": "pkg/scheduler/OWNERS", ..., "dims": "OWNERS"},
        "reviewers": {...},
        "source": "pkg/scheduler/OWNERS"}

`approvers` and `reviewers` map each login to the OWNERS file that lists it (use set(...) for
just the logins). `source` is the nearest OWNERS file. Works for file and folder paths.

Reads data/k8s-owners, a sparse clone that holds only OWNERS and OWNERS_ALIASES (see README).
Import it with scripts/ on sys.path; running `python scripts/<name>.py` does that.

Rules (the ones Prow, Kubernetes' merge bot, uses):
- Start at the nearest OWNERS file (the path's own folder, else the closest parent), then add
  every OWNERS file above it up to the repo root. Stop after a file with
  `options: no_parent_owners: true`. If a login is listed twice, the closest file wins.
- Each file's `approvers` and `reviewers` are merged with every list under its `filters:`.
  `emeritus_*` (former owners) and `required_reviewers` (GitHub teams) are ignored.
- Team names are expanded with OWNERS_ALIASES. Logins then go through logins.clean_login:
  lowercased, fixed with data/aliases.yaml, bots dropped.
"""
from functools import lru_cache
from pathlib import Path

import yaml

from logins import clean_login

OWNERS_DIR = Path(__file__).resolve().parent.parent / "data" / "k8s-owners"
TEAM_SUFFIXES = ("-approvers", "-reviewers", "-maintainers", "-leads")

# Team names used in OWNERS files but missing from OWNERS_ALIASES (e.g. 'sig-testing-leads').
# They are not people, so they are skipped; loaders can print this set.
unknown_teams = set()


@lru_cache(maxsize=None)
def _aliases():
    data = yaml.safe_load((OWNERS_DIR / "OWNERS_ALIASES").read_text(encoding="utf-8")) or {}
    return {str(k).lower(): [str(x) for x in (v or [])] for k, v in (data.get("aliases") or {}).items()}


def _people(names):
    """Expand team aliases, then clean each login. Returns logins in file order, no repeats."""
    out = []
    for name in names:
        name = str(name).strip().lower()
        if name in _aliases():
            members = _aliases()[name]
        elif name.endswith(TEAM_SUFFIXES):
            unknown_teams.add(name)
            continue
        else:
            members = [name]
        out += [login for login in map(clean_login, members) if login]
    return list(dict.fromkeys(out))


@lru_cache(maxsize=None)
def owners_files():
    """{folder: {"approvers": [...], "reviewers": [...], "stop": bool}} for every OWNERS file.
    The repo root is ''. `stop` means no_parent_owners."""
    if not (OWNERS_DIR / "OWNERS").exists():
        raise FileNotFoundError(f"No OWNERS files in {OWNERS_DIR}: run the sparse clone from the README.")
    files = {}
    for f in OWNERS_DIR.rglob("OWNERS"):
        rel = f.relative_to(OWNERS_DIR)
        if ".git" in rel.parts:
            continue
        data = yaml.safe_load(f.read_text(encoding="utf-8")) or {}
        blocks = [data] + [b or {} for b in (data.get("filters") or {}).values()]
        entry = {role: _people([name for b in blocks for name in b.get(role) or []])
                 for role in ("approvers", "reviewers")}
        entry["stop"] = bool((data.get("options") or {}).get("no_parent_owners"))
        folder = rel.parent.as_posix()  # forward slashes on Windows too
        files["" if folder == "." else folder] = entry
    return files


def owners_for_path(path):
    """Official approvers and reviewers of a file or folder, e.g. 'pkg/scheduler/framework'."""
    files = owners_files()
    parts = [p for p in path.replace("\\", "/").split("/") if p]
    result = {"approvers": {}, "reviewers": {}, "source": None}
    for depth in range(len(parts), -1, -1):  # the path itself, then each parent, then the root
        folder = "/".join(parts[:depth])
        if folder not in files:
            continue
        src = f"{folder}/OWNERS" if folder else "OWNERS"
        result["source"] = result["source"] or src
        for role in ("approvers", "reviewers"):
            for login in files[folder][role]:
                result[role].setdefault(login, src)
        if files[folder]["stop"]:
            break
    return result

"""
Download 12 months of merged PRs and issues from kubernetes/kubernetes
for the 5 slice teams, using GitHub's GraphQL API.

What is GraphQL? A single API endpoint (POST https://api.github.com/graphql)
where we describe exactly which fields we want. One call returns up to 50 PRs
*with* their files, reviews and comments, instead of 3+ REST calls per PR.

Privacy: we keep only GitHub logins and public activity (numbers, titles,
labels, file paths, timestamps). No emails, no names, no PR descriptions,
no issue or comment bodies. Comment bodies are read only to set two flags
(/lgtm and /approve lines) and are then thrown away.

Cache: each (type, team, month) is saved to
    data/raw/<prs|issues>/<team>/<YYYY-MM>.json
If that file exists it is skipped, so re-running continues where it stopped.

Usage:
    python scripts/fetch_github.py                                # everything
    python scripts/fetch_github.py --teams sig-scheduling --months 2026-09
"""

import argparse
import json
import os
import time
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

import requests
from dotenv import load_dotenv

load_dotenv()

# ── config ──────────────────────────────────────────────────────────────
REPO = "kubernetes/kubernetes"
TEAMS = ["sig-node", "sig-scheduling", "sig-auth", "sig-storage", "sig-network"]
START = date(2025, 10, 18)   # first day included
END = date(2026, 10, 18)     # last day included
RAW = Path("data/raw")

GRAPHQL_URL = "https://api.github.com/graphql"
PAGE_SIZE = 50             # items per call
SMALLER_PAGES = (20, 10)   # after each timeout, step down to the next size
TIMEOUT_WAIT = 30          # seconds to wait after a timeout before retrying
MIN_REMAINING = 200        # below this many points left, sleep until the reset
MAX_TRIES = 5

TOKEN = [REDACTED]"GITHUB_TOKEN", "")
if not TOKEN:
    raise SystemExit("GITHUB_TOKEN is missing. Put GITHUB_TOKEN=... in .env")
HEADERS = {"Authorization": f"Bearer {TOKEN}"}


# ── GraphQL queries ─────────────────────────────────────────────────────
# `search` returns at most 1000 results per query, so we query one month at a time.
PR_QUERY = """
query($q: String!, $n: Int!, $after: String) {
  rateLimit { remaining resetAt cost }
  search(query: $q, type: ISSUE, first: $n, after: $after) {
    issueCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on PullRequest {
        number title createdAt mergedAt
        author { login }
        labels(first: 50) { nodes { name } }
        files(first: 100) { totalCount nodes { path } }
        reviews(first: 50) { totalCount nodes { author { login } state submittedAt } }
        comments(first: 100) { totalCount nodes { author { login } createdAt body } }
      }
    }
  }
}
"""

ISSUE_QUERY = """
query($q: String!, $n: Int!, $after: String) {
  rateLimit { remaining resetAt cost }
  search(query: $q, type: ISSUE, first: $n, after: $after) {
    issueCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Issue {
        number title createdAt closedAt state
        author { login }
        labels(first: 50) { nodes { name } }
        assignees(first: 20) { nodes { login } }
        comments(first: 50) { totalCount nodes { author { login } createdAt } }
      }
    }
  }
}
"""


# ── helpers ─────────────────────────────────────────────────────────────
def login(actor):
    """Author can be null when the account was deleted."""
    return actor["login"] if actor else None


def has_line_starting(body, command):
    """True if any line of the comment starts with e.g. '/lgtm'."""
    return any(line.strip().startswith(command) for line in (body or "").splitlines())


def month_ranges():
    """Yield ("2025-10", first_day, last_day) for each month, clipped to START..END."""
    y, m = START.year, START.month
    while date(y, m, 1) <= END:
        first = date(y, m, 1)
        nxt = date(y + (m == 12), m % 12 + 1, 1)
        yield f"{y:04d}-{m:02d}", max(first, START), min(nxt - timedelta(days=1), END)
        y, m = nxt.year, nxt.month


def wait_for_rate_limit(rate):
    if rate["remaining"] < MIN_REMAINING:
        reset = datetime.fromisoformat(rate["resetAt"].replace("Z", "+00:00"))
        wait = max((reset - datetime.now(timezone.utc)).total_seconds() + 5, 1)
        print(f"    [rate limit] {rate['remaining']} points left, sleeping {wait:.0f}s", flush=True)
        time.sleep(wait)


class Timeout(Exception):
    """GitHub didn't give a full answer in time. The caller waits and retries with smaller pages."""


def post(query, variables):
    """One GraphQL call with retries. Returns the `data` part of the answer."""
    for attempt in range(1, MAX_TRIES + 1):
        try:
            resp = requests.post(GRAPHQL_URL, json={"query": query, "variables": variables},
                                 headers=HEADERS, timeout=90)
        except requests.exceptions.Timeout:
            raise Timeout("no answer within 90s")
        except (requests.exceptions.ConnectionError, requests.exceptions.ChunkedEncodingError) as e:
            raise Timeout(f"connection error: {e}")

        if resp.status_code == 504:
            raise Timeout("HTTP 504")
        text = resp.text.lower()
        if resp.status_code in (502, 503) or "secondary rate limit" in text:
            if resp.status_code == 502 and variables["n"] == PAGE_SIZE:
                raise Timeout("HTTP 502")  # probably too big a page
            print(f"    [retry {attempt}/{MAX_TRIES}] HTTP {resp.status_code}, waiting 60s", flush=True)
            time.sleep(60)
            continue
        resp.raise_for_status()

        try:
            body = resp.json()
        except requests.exceptions.JSONDecodeError as e:
            raise Timeout(f"cut-off answer ({e})")
        errors = body.get("errors") or []
        if any(e.get("type") == "RATE_LIMITED" for e in errors):
            print(f"    [retry {attempt}/{MAX_TRIES}] rate limited, waiting 60s", flush=True)
            time.sleep(60)
            continue
        if any("timeout" in (e.get("message") or "").lower() for e in errors):
            raise Timeout(errors[0]["message"])
        if errors:
            raise RuntimeError(f"GraphQL error: {errors}")
        return body["data"]
    raise RuntimeError(f"gave up after {MAX_TRIES} tries")


# ── turning API answers into our saved shape ────────────────────────────
def clean_pr(n):
    return {
        "number": n["number"],
        "title": n["title"],
        "author": login(n["author"]),
        "createdAt": n["createdAt"],
        "mergedAt": n["mergedAt"],
        "labels": [l["name"] for l in n["labels"]["nodes"]],
        "files": [f["path"] for f in n["files"]["nodes"]],
        "files_total": n["files"]["totalCount"],
        "reviews": [{"author": login(r["author"]), "state": r["state"],
                     "submittedAt": r["submittedAt"]} for r in n["reviews"]["nodes"]],
        "reviews_total": n["reviews"]["totalCount"],
        "comments": [{"author": login(c["author"]), "createdAt": c["createdAt"],
                      "lgtm": has_line_starting(c["body"], "/lgtm"),
                      "approve": has_line_starting(c["body"], "/approve")}
                     for c in n["comments"]["nodes"]],   # body is dropped here
        "comments_total": n["comments"]["totalCount"],
    }


def clean_issue(n):
    return {
        "number": n["number"],
        "title": n["title"],
        "author": login(n["author"]),
        "createdAt": n["createdAt"],
        "closedAt": n["closedAt"],
        "state": n["state"],
        "labels": [l["name"] for l in n["labels"]["nodes"]],
        "assignees": [a["login"] for a in n["assignees"]["nodes"]],
        "comments": [{"author": login(c["author"]), "createdAt": c["createdAt"]}
                     for c in n["comments"]["nodes"]],
        "comments_total": n["comments"]["totalCount"],
    }


# ── fetching one (type, team, month) ────────────────────────────────────
def fetch_bucket(kind, team, month, first, last):
    dest = RAW / f"{kind}s" / team / f"{month}.json"
    if dest.exists():
        print(f"  {kind:5} {team:15} {month}  cached, skipped", flush=True)
        return

    label = "sig/" + team[len("sig-"):]
    days = f"{first.isoformat()}..{last.isoformat()}"
    if kind == "pr":
        q = f"repo:{REPO} is:pr is:merged label:{label} merged:{days}"
        query, clean = PR_QUERY, clean_pr
    else:
        q = f"repo:{REPO} is:issue label:{label} created:{days}"
        query, clean = ISSUE_QUERY, clean_issue

    items, after, n, calls, left, total = [], None, PAGE_SIZE, 0, None, 0
    tries = 0  # failed tries for the current page
    while True:
        try:
            data = post(query, {"q": q, "n": n, "after": after})
        except Timeout as e:
            tries += 1
            if tries >= MAX_TRIES:
                raise RuntimeError(f"gave up after {MAX_TRIES} tries: {e}") from e
            n = next((s for s in SMALLER_PAGES if s < n), n)  # 50 -> 20 -> 10, then stays 10
            print(f"    [timeout {tries}/{MAX_TRIES}] {e}; waiting {TIMEOUT_WAIT}s, "
                  f"then pages of {n}", flush=True)
            time.sleep(TIMEOUT_WAIT)
            continue
        tries = 0
        calls += 1
        rate, search = data["rateLimit"], data["search"]
        left, total = rate["remaining"], search["issueCount"]
        items += [clean(node) for node in search["nodes"] if node]
        wait_for_rate_limit(rate)
        if not search["pageInfo"]["hasNextPage"]:
            break
        after = search["pageInfo"]["endCursor"]

    if total > 1000:
        print(f"    WARNING: {total} results but search stops at 1000; split this month", flush=True)

    # Write to a temp file first, then rename: a half-written file is never left behind
    # (it would otherwise be "cached" and skipped forever).
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(".tmp")
    tmp.write_text(json.dumps({
        "type": kind, "team": team, "month": month, "range": days, "search": q,
        "fetched_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "count": len(items), "items": items,
    }, indent=1, ensure_ascii=False), encoding="utf-8")
    tmp.replace(dest)
    print(f"  {kind:5} {team:15} {month}  {len(items):4} items  "
          f"({calls} calls, {left} points left)", flush=True)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--teams", nargs="+", default=TEAMS, choices=TEAMS)
    ap.add_argument("--months", nargs="+", help="e.g. 2026-09 (default: all 12 months)")
    args = ap.parse_args()

    months = [m for m in month_ranges() if not args.months or m[0] in args.months]
    started = time.time()
    for team in args.teams:
        for month, first, last in months:
            for kind in ("pr", "issue"):
                fetch_bucket(kind, team, month, first, last)
    print(f"Done in {time.time() - started:.0f}s")


if __name__ == "__main__":
    main()

"""Answer /api/ask from the graph when no LLM agent is configured.

Picks one of app/tools.py's Cypher tools for the question and returns its envelope
({tool, summary, data, evidence, sources, is_stub}) plus the fields the web page reads
(answer, official_owners, actual_knowers, decision_trail, graph).
"""
import re
from typing import Any, Dict

from app import tools

STALE = re.compile(r"\b(stuck|stale|abandon\w*|forgotten|dead)\b", re.I)
WHY = re.compile(r"^\s*(why|how come)\b|\b(decid\w*|decision|history|trail)\b", re.I)
GATE = re.compile(r"\b[A-Z][a-z]+(?:[A-Z][a-z0-9]+)+\b")
WHY_PREFIX = re.compile(r"^\s*(why|how come)(\s+(did|do|does|was|were|is))?(\s+(they|we|kubernetes|k8s))?"
                        r"(\s+(choose|chose|pick|use|decide on|go with|add|remove))?\s*", re.I)
OWN = re.compile(r"\b(who owns|owner|owners|official)\b", re.I)
KEP = re.compile(r"\bKEP[-\s#]*(\d+)\b", re.I)
ISSUE = re.compile(r"\b(new issue|issue titled|bug report|triage|route this|where should this go)\b", re.I)
QUOTED = re.compile(r"[\"“]([^\"”]{5,200})[\"”]")
ROLE_TEXT = {"kep_approver": "KEP approver", "tech_lead": "tech lead"}


TEAM = re.compile(r"\b(sig|wg)[\s-]+([a-z]+)(?:[\s-]([a-z]+))?", re.I)


def _team_in(q: str):
    """The Team a question names ('SIG Node', 'sig-storage', 'wg batch'), else None."""
    for m in TEAM.finditer(q):
        kind, a, b = m.groups()
        for cand in ([f"{kind}-{a}-{b}"] if b else []) + [f"{kind}-{a}"]:
            key = tools._find_team(cand.lower())
            if key:
                return key
    return None


def _pick(question: str):
    q = question.strip()
    team = _team_in(q)
    m = KEP.search(q)
    kep = f"kep:{int(m.group(1))}" if m else None
    owns = bool(OWN.search(q)) and "know" not in q.lower()
    if ISSUE.search(q):  # a pasted issue: route it (checked first, so "stuck" in a title isn't a stale question)
        title = QUOTED.search(q)
        return tools.route_issue(title.group(1) if title else q, q)
    if STALE.search(q):
        return tools.whats_stale(team)
    gate = next((g for g in GATE.findall(q) if tools._resolve(f"gate:{g}")[0] == "gate"), None)
    if WHY.search(q):
        return tools.why(kep or gate or WHY_PREFIX.sub("", q).strip(" ?.") or q)
    if gate:
        return tools.who_knows(f"gate:{gate}")
    if kep:  # 'Who owns KEP-4671?' / 'Who knows KEP-4671?' / anything else about it: its trail
        if owns:
            return tools.who_owns(kep)
        return tools.who_knows(kep) if "know" in q.lower() else tools.why(kep)
    if team:
        return tools.who_owns(f"team:{team}") if owns else tools.who_knows(f"team:{team}")
    folder = re.search(r"\b[\w.-]+(?:/[\w.-]+)+\b", q)
    if folder and tools._resolve(f"folder:{folder.group(0)}")[0] == "folder":
        return tools.who_knows(f"folder:{folder.group(0)}")
    env = tools.why(q)
    if (env.get("data") or {}).get("thing", "found") is None:  # nothing matched at all
        env["summary"] = ("Lore only knows Kubernetes teams, design decisions (KEPs), code folders and their "
                          "people, and found nothing matching this question. Try a team (\"sig-node\"), a KEP "
                          "(\"KEP-4671\") or a folder (\"pkg/kubelet\").")
    return env


def _official_owners(data: Dict[str, Any]):
    """Official owners in the page's shape ({login, role}) from any who_owns / who_knows result:
    team leaders, a KEP's team leaders and approvers, or a folder's OWNERS approvers."""
    roles: Dict[str, list] = {}

    def add(login, role):
        if login and role not in roles.setdefault(login, []):
            roles[login].append(role)
    for o in data.get("official_owners") or data.get("owners") or []:
        for r in o.get("roles") or ["official owner"]:
            add(o.get("login"), ROLE_TEXT.get(r, r))
    for o in data.get("team_leads") or []:
        add(o.get("login"), f"{data.get('team')} " + ", ".join(ROLE_TEXT.get(r, r) for r in o.get("roles") or ["lead"]))
    for o in data.get("approvers") or []:
        add(o.get("login"), f"approver ({o['source']})" if o.get("source") else "KEP approver")
    return [{"login": login, "role": ", ".join(rs)} for login, rs in roles.items()]


def answer(question: str) -> Dict[str, Any]:
    env = _pick(question)
    data = env.get("data") or {}
    out: Dict[str, Any] = dict(env)
    out["answer"] = env.get("summary", "")
    out["official_owners"] = _official_owners(data)
    out["actual_knowers"] = [{"login": p["login"], "is_official": p.get("is_official_owner", False),
                              "decisions_count": p.get("total", 0)} for p in data.get("people") or []][:8]
    out["decision_trail"] = [{"kep": k["ref"], "title": k["title"], "date": (k.get("created") or "")[:7],
                              "status": k.get("status") or ""} for k in data.get("trail") or []]
    ev = env.get("evidence") or {}
    out["graph"] = {"nodes": ev.get("nodes", []), "edges": ev.get("edges", [])}
    # Same shape as the agent's answer: the step taken (the page shows its owners/knowers
    # panel from it) and, for a routed issue, the draft comment.
    out["steps"] = [{"tool": env.get("tool"), "input": {"question": question}, "summary": env.get("summary", "")}]
    if data.get("draft_comment"):
        out["draft"] = {"comment": data["draft_comment"], "label": data.get("label")}
    return out
